import{_ as e,o as i,c as a,a6 as t}from"./chunks/framework.ZMCvXf1_.js";const k=JSON.parse('{"title":"Vault","description":"","frontmatter":{},"headers":[],"relativePath":"guide/environments/vault.md","filePath":"guide/environments/vault.md"}'),n={name:"guide/environments/vault.md"};function l(r,s,h,o,p,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="vault" tabindex="-1">Vault <a class="header-anchor" href="#vault" aria-label="Permalink to “Vault”">​</a></h1><p>Team-shared secrets need to live somewhere everyone can access them. Local secrets stay on your machine, but what about API keys that the whole team needs? The vault stores encrypted secrets in the database itself, distributing them to team members automatically.</p><h2 id="secret-resolution-hierarchy" tabindex="-1">Secret Resolution Hierarchy <a class="header-anchor" href="#secret-resolution-hierarchy" aria-label="Permalink to “Secret Resolution Hierarchy”">​</a></h2><p>When a template references <code>secrets.API_KEY</code>, noorm checks three sources in order. The first match wins:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  1. Config-specific local secret         (highest priority) │</span></span>
<span class="line"><span>│     Your override for this specific config                  │</span></span>
<span class="line"><span>│     Location: .noorm/state/state.enc                        │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  2. Global local secret                                     │</span></span>
<span class="line"><span>│     Your shared secret across all configs                   │</span></span>
<span class="line"><span>│     Location: .noorm/state/state.enc                        │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  3. Vault secret                          (lowest priority) │</span></span>
<span class="line"><span>│     Team-shared value from the database                     │</span></span>
<span class="line"><span>│     Location: the vault table                               │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>Local always wins.</strong> This lets you override team secrets for testing without affecting others.</p><h3 id="example-overriding-a-team-secret" tabindex="-1">Example: Overriding a Team Secret <a class="header-anchor" href="#example-overriding-a-team-secret" aria-label="Permalink to “Example: Overriding a Team Secret”">​</a></h3><p>Your team stores the production Stripe key in the vault:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vault:  STRIPE_KEY = &quot;sk_live_abc123...&quot;</span></span></code></pre></div><p>For local development, you want to use Stripe&#39;s test mode. Set a local override through the TUI: <code>noorm ui</code> → Config → highlight the config → <code>k</code> → <code>a</code>, with key <code>STRIPE_KEY</code> and value <code>sk_test_xyz789...</code>. Headlessly, <code>noorm secret set STRIPE_KEY &quot;sk_test_xyz789...&quot;</code>. Local secrets are stored encrypted in your <code>.noorm/state/state.enc</code> and never leave your machine.</p><p>Now when templates reference <code>secrets.STRIPE_KEY</code>:</p><table tabindex="0"><thead><tr><th>Context</th><th>Resolved Value</th><th>Source</th></tr></thead><tbody><tr><td>Your machine</td><td><code>sk_test_xyz789...</code></td><td>Local (your override)</td></tr><tr><td>Teammate&#39;s machine</td><td><code>sk_live_abc123...</code></td><td>Vault (no local override)</td></tr><tr><td>CI/CD pipeline</td><td><code>sk_live_abc123...</code></td><td>Vault (no local override)</td></tr></tbody></table><p>Your local override doesn&#39;t affect anyone else.</p><h3 id="when-to-use-each-layer" tabindex="-1">When to Use Each Layer <a class="header-anchor" href="#when-to-use-each-layer" aria-label="Permalink to “When to Use Each Layer”">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Use When</th></tr></thead><tbody><tr><td><strong>Config-specific local</strong></td><td>Testing with different credentials per environment</td></tr><tr><td><strong>Global local</strong></td><td>Personal API keys you use across all configs</td></tr><tr><td><strong>Vault</strong></td><td>Team-shared secrets everyone needs</td></tr></tbody></table><h2 id="how-encryption-works" tabindex="-1">How Encryption Works <a class="header-anchor" href="#how-encryption-works" aria-label="Permalink to “How Encryption Works”">​</a></h2><p>The vault uses dual-layer encryption to share secrets securely:</p><p><strong>Layer 1: Vault Key Distribution</strong></p><p>A single 256-bit vault key encrypts all secrets. Each team member receives their own encrypted copy of this key:</p><ol><li>Generate ephemeral X25519 keypair</li><li>Perform ECDH with recipient&#39;s public key</li><li>Derive encryption key via HKDF-SHA256</li><li>Encrypt vault key with AES-256-GCM</li><li>Store in user&#39;s <code>encrypted_vault_key</code> column</li></ol><p>When you connect, noorm decrypts your copy of the vault key using your private identity key.</p><p><strong>Layer 2: Secret Encryption</strong></p><p>Individual secrets are encrypted with the shared vault key:</p><ul><li>AES-256-GCM authenticated encryption</li><li>Random IV per secret</li><li>Stored as JSON in the vault table</li></ul><p>This design means: compromising the database alone doesn&#39;t expose secrets. An attacker needs both database access AND a team member&#39;s private key.</p><h2 id="initializing-the-vault" tabindex="-1">Initializing the Vault <a class="header-anchor" href="#initializing-the-vault" aria-label="Permalink to “Initializing the Vault”">​</a></h2><p>The first team member to initialize creates the vault key:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>This generates a new vault key and stores it encrypted for your identity. Only one person needs to do this per database.</p><p>If someone else already initialized:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vault already initialized but you do not have access.</span></span>
<span class="line"><span>Ask a team member to propagate.</span></span></code></pre></div><h2 id="managing-secrets" tabindex="-1">Managing Secrets <a class="header-anchor" href="#managing-secrets" aria-label="Permalink to “Managing Secrets”">​</a></h2><p>Once you have vault access, manage secrets with these commands:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set a secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;sk-live-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DB_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;secret123&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List all secrets (values hidden)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove a secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OLD_API_KEY</span></span></code></pre></div><p>The TUI provides a visual interface at <strong>Vault</strong> (<code>v</code> from home):</p><ul><li>View all vault secrets, each labeled with who set it</li><li>Add a secret with <code>a</code>, edit one by selecting it</li><li>See pending users who need access</li><li>One-key propagation (<code>p</code>)</li></ul><p>Removing a vault secret is CLI-only: <code>noorm vault rm &lt;KEY&gt;</code>.</p><h2 id="granting-team-access" tabindex="-1">Granting Team Access <a class="header-anchor" href="#granting-team-access" aria-label="Permalink to “Granting Team Access”">​</a></h2><p>New team members register their identity but don&#39;t automatically get vault access. Someone with access must propagate the key:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> propagate</span></span></code></pre></div><p>This encrypts the vault key for each pending user&#39;s public key. After propagation, they can decrypt vault secrets on their next connection.</p><p>The Vault screen counts them in its header:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>3 secret(s) | 4 user(s) with access   (2 pending)</span></span></code></pre></div><p>Press <code>p</code> there to propagate. noorm lists the recipients it is about to grant access to and asks you to confirm before it writes anything.</p><h2 id="copying-secrets-between-configs" tabindex="-1">Copying Secrets Between Configs <a class="header-anchor" href="#copying-secrets-between-configs" aria-label="Permalink to “Copying Secrets Between Configs”">​</a></h2><p>Move a secret from one database to another. <code>vault cp</code> takes three positional arguments in this order: the key, the source config, and the destination config. All three are required, so copy one key per invocation.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy one secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Overwrite a key that already exists on the destination</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Preview without writing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>A dry run performs the same preflight as a real copy (vault access on both ends, source key exists, destination collisions) and only skips the write.</p><p>If the destination vault isn&#39;t initialized, noorm initializes it automatically using your identity.</p><h2 id="using-vault-secrets-in-templates" tabindex="-1">Using Vault Secrets in Templates <a class="header-anchor" href="#using-vault-secrets-in-templates" aria-label="Permalink to “Using Vault Secrets in Templates”">​</a></h2><p>Vault secrets merge into the template context alongside local secrets:</p><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- sql/setup/external-api.sql.tmpl</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Vault secret (or local override if set)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api_config (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;stripe&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {%~ $.quote($.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">secrets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">STRIPE_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) %});</span></span></code></pre></div><p>The resolution order means you can:</p><ol><li>Store production <code>STRIPE_KEY</code> in the vault</li><li>Override with a test key locally for development</li><li>Templates work identically in both cases</li></ol><h2 id="ci-cd-integration" tabindex="-1">CI/CD Integration <a class="header-anchor" href="#ci-cd-integration" aria-label="Permalink to “CI/CD Integration”">​</a></h2><p>Vault commands run non-interactively, so you can manage secrets straight from a pipeline:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Initialize vault</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set secret (value as argument)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List with JSON output</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy a secret between environments</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span></span></code></pre></div><p>Pipe the value in with <code>--stdin</code> to keep it out of the process table, shell history, and <code>set -x</code> traces:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SECRET_VALUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MY_SECRET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stdin</span></span></code></pre></div><h2 id="security-considerations" tabindex="-1">Security Considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to “Security Considerations”">​</a></h2><p>The vault design provides several security properties:</p><ol><li><strong>End-to-end encryption</strong> - Secrets encrypted in memory, transmitted encrypted, stored encrypted</li><li><strong>Zero-knowledge database</strong> - Database administrators see only ciphertext</li><li><strong>Per-user key distribution</strong> - Propagation re-encrypts the same vault key for each recipient, so every user holds unique ciphertext</li><li><strong>No shared secrets in transit</strong> - ECDH derives keys without transmitting them</li><li><strong>Authenticated encryption</strong> - AES-256-GCM detects tampering</li></ol><p>Limitations to understand:</p><ul><li>Team members with vault access can read all vault secrets</li><li>Removing access requires regenerating the vault key (not yet supported)</li><li>Lost private keys mean lost vault access (identity must be re-registered)</li></ul><h2 id="database-schema" tabindex="-1">Database Schema <a class="header-anchor" href="#database-schema" aria-label="Permalink to “Database Schema”">​</a></h2><p>The vault uses two database structures. Their names depend on the dialect: PostgreSQL and SQL Server put noorm&#39;s tracking tables in a dedicated <code>noorm</code> schema (<code>noorm.vault</code>, <code>noorm.identities</code>), while MySQL and SQLite have no schemas and keep the prefixed forms (<code>__noorm_vault__</code>, <code>__noorm_identities__</code>) in the default schema.</p><p><strong>The vault table:</strong></p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>int</td><td>Primary key</td></tr><tr><td><code>secret_key</code></td><td>string</td><td>Secret name (unique)</td></tr><tr><td><code>encrypted_value</code></td><td>text</td><td>AES-256-GCM ciphertext (JSON)</td></tr><tr><td><code>set_by</code></td><td>string</td><td>Identity who set it</td></tr><tr><td><code>created_at</code></td><td>timestamp</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>timestamp</td><td>Last update time</td></tr></tbody></table><p><strong>The identities table extension:</strong></p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>encrypted_vault_key</code></td><td>text</td><td>Vault key encrypted for this user (nullable)</td></tr></tbody></table><p>A null <code>encrypted_vault_key</code> means the user is pending vault access.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><ul><li><a href="/guide/environments/secrets.html">Secrets</a> - Local secret storage</li><li><a href="/cli/identity.html">Identity</a> - The keypair that lets teammates encrypt secrets to you</li><li><a href="/guide/sql-files/templates.html">Templates</a> - Using secrets in dynamic SQL</li></ul>`,73)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
